const req = $('Webhook').first().json.body || $('Webhook').first().json;
const centerCode = (req.center_code || '').trim().toUpperCase();
const reportDate = (req.report_date || '').trim();

const allRows = $input.all();
const filtered = [];

for (const it of allRows) {
  const row = it.json;
  const rowCenter = String(row['Mã TTBH'] || '').trim().toUpperCase();
  const rowDate = String(row['Ngày báo cáo'] || '').trim();

  if (centerCode && rowCenter !== centerCode) continue;
  if (reportDate && reportDate.toUpperCase() !== 'ALL' && rowDate !== reportDate) continue;

  filtered.push(row);
}

const totalRows = filtered.length;
const totalUnitPrice = filtered.reduce((acc, r) => acc + (parseFloat(r['Đơn giá']) || 0), 0);
const totalCash = filtered.reduce((acc, r) => acc + (parseFloat(r['Doanh thu tiền mặt']) || 0), 0);
const totalDebt = filtered.reduce((acc, r) => acc + (parseFloat(r['Công nợ']) || 0), 0);
const totalWarrantyExport = filtered.reduce((acc, r) => acc + (parseInt(r['Xuất Bảo Hành']) || 0), 0);
const totalRepairExport = filtered.reduce((acc, r) => acc + (parseInt(r['Xuất Sửa Chữa']) || 0), 0);
const countKl = filtered.filter(r => r['Khách hàng'] === 'KL').length;
const countTgdd = filtered.filter(r => r['Khách hàng'] === 'TGDĐ').length;

return [{
  json: {
    success: true,
    center_code: centerCode,
    report_date: reportDate,
    summary: {
      totalRows,
      totalUnitPrice,
      totalCash,
      totalDebt,
      totalWarrantyExport,
      totalRepairExport,
      countKl,
      countTgdd
    },
    rows: filtered
  }
}];
